// Runtime helpers for the shared audio bank (generated by scripts/bank-prompts.ts).
// These build the audio keys and the chained sequences played during spelling.
// No audio text lives here - only key strings.

export const BANK = {
  uhoh: 'bank.uhoh',
  lookingFor: 'bank.lookingFor',
  thisIsTheWord: 'bank.thisIsTheWord',
  pressTheOne: 'bank.pressTheOne',
  great: 'bank.great',
  youSpelled: 'bank.youSpelled',
  spellEnd: 'bank.spellEnd',
} as const;

export const nameKey = (letter: string): string => `bank.name.${letter.toUpperCase()}`;

export const soundKey = (letter: string, variant?: string | null): string =>
  variant ? `bank.sound.${letter.toUpperCase()}.${variant}` : `bank.sound.${letter.toUpperCase()}`;

export const wordKey = (word: string): string => `word.${word.toLowerCase()}`;

// Short, snappy placement feedback: name then sound → "C, kuh". Kept to two
// clips so it finishes before a quick toddler drops the next letter (longer
// chains were getting cut off). A silent letter just says its name.
export const placementSeq = (letter: string, variant?: string | null): string[] =>
  variant === 'silent'
    ? [nameKey(letter)]
    : [nameKey(letter), soundKey(letter, variant)];

// "Uh-oh! We are looking for the letter… C."
export const wrongSeq = (expected: string): string[] => [
  BANK.uhoh,
  BANK.lookingFor,
  nameKey(expected),
];

// Word-recognition correction: "Uh-oh! This is the word… MAT. You need to press
// the one that says… CAT." Names what they actually tapped before re-asking, so
// a wrong tap teaches a word instead of just buzzing. Must be played as ONE
// sequence - a follow-up audio.play() cuts the chain off mid-clip.
export const wrongWordSeq = (tapped: string, expected: string): string[] => [
  BANK.uhoh,
  BANK.thisIsTheWord,
  wordKey(tapped),
  BANK.pressTheOne,
  wordKey(expected),
];

// "Great job! You spelled cat. C, kuh. A, aaa. T, tuh. And that is how you spell
// cat." Names AND sounds per letter to reinforce both; this is the gated recap
// the child must hear fully before the Continue button appears.
export const completionSeq = (
  word: string,
  letters: string[],
  sounds: (string | null)[] = []
): string[] => [
  BANK.great,
  BANK.youSpelled,
  wordKey(word),
  ...letters.flatMap((l, i) =>
    sounds[i] === 'silent' ? [nameKey(l)] : [nameKey(l), soundKey(l, sounds[i] ?? null)]
  ),
  BANK.spellEnd,
  wordKey(word),
];
